import 'package:uuid/uuid.dart';
import 'local_database.dart';
import '../domain/finance_models.dart';
import '../domain/finance_engine.dart';
class FinanceStore {
 final _uuid=const Uuid(); final List<FinanceAccount> accounts=[]; final List<FinanceCategory> categories=[]; final List<FinanceTransaction> transactions=[];
 Future<void> init() async {final db=await LocalDatabase.instance.database;for(final r in await db.query('accounts')){accounts.add(FinanceAccount(id:r['id'] as String,name:r['name'] as String,openingBalance:r['opening_balance'] as int));}for(final r in await db.query('categories')){categories.add(FinanceCategory(id:r['id'] as String,name:r['name'] as String,type:TransactionType.values.firstWhere((e)=>e.name==r['type'])));}if(accounts.isEmpty){await addAccount('Ví tiền mặt',0);await addAccount('Tài khoản ngân hàng',0);}if(categories.isEmpty)await _seedCategories();await refresh();}
 Future<void> _seedCategories() async {final defaults=<(String,TransactionType)>[('Lương',TransactionType.income),('Thu nhập khác',TransactionType.income),('Ăn uống',TransactionType.expense),('Di chuyển',TransactionType.expense),('Mua sắm',TransactionType.expense),('Nhà cửa',TransactionType.expense),('Hóa đơn',TransactionType.expense),('Sức khỏe',TransactionType.expense),('Khác',TransactionType.expense),('Chuyển khoản',TransactionType.transfer)];final db=await LocalDatabase.instance.database;for(final item in defaults){final c=FinanceCategory(id:_uuid.v4(),name:item.$1,type:item.$2);categories.add(c);await db.insert('categories',{'id':c.id,'name':c.name,'type':c.type.name});}}
 Future<void> addAccount(String name,int openingBalance) async {final a=FinanceAccount(id:_uuid.v4(),name:name,openingBalance:openingBalance);accounts.add(a);await (await LocalDatabase.instance.database).insert('accounts',{'id':a.id,'name':name,'opening_balance':openingBalance});}
 Future<void> addTransaction({required String accountId,required int amount,required TransactionType type,required String categoryId,required String note,required DateTime date,String? batchId}) async {await _insert(FinanceTransaction(id:_uuid.v4(),accountId:accountId,amount:amount,type:type,categoryId:categoryId,note:note,date:date,status:'posted',batchId:batchId));}
 Future<void> transfer({required String sourceAccountId,required String destinationAccountId,required int amount,required String categoryId,required String note,required DateTime date}) async {if(sourceAccountId==destinationAccountId||amount<=0)throw ArgumentError('Tài khoản nguồn và nhận phải khác nhau; số tiền phải lớn hơn 0.');final tx=FinanceTransaction(id:_uuid.v4(),accountId:sourceAccountId,destinationAccountId:destinationAccountId,amount:amount,type:TransactionType.transfer,categoryId:categoryId,note:note,date:date,status:'posted');await _insert(tx);await (await LocalDatabase.instance.database).insert('audit_log',{'action':'transfer','entity_id':tx.id,'created_at':DateTime.now().toIso8601String()});}
 Future<void> _insert(FinanceTransaction tx) async {final db=await LocalDatabase.instance.database;await db.insert('transactions',{'id':tx.id,'account_id':tx.accountId,'destination_account_id':tx.destinationAccountId,'amount':tx.amount,'type':tx.type.name,'category_id':tx.categoryId,'note':tx.note,'date':tx.date.toIso8601String(),'status':tx.status,'batch_id':tx.batchId});transactions.add(tx);}
 Future<void> refresh() async {final rows=await (await LocalDatabase.instance.database).query('transactions');transactions..clear()..addAll(rows.map((r)=>FinanceTransaction(id:r['id'] as String,accountId:r['account_id'] as String,destinationAccountId:r['destination_account_id'] as String?,amount:r['amount'] as int,type:TransactionType.values.firstWhere((e)=>e.name==r['type']),categoryId:r['category_id'] as String,note:r['note'] as String,date:DateTime.parse(r['date'] as String),status:r['status'] as String,batchId:r['batch_id'] as String?)));}
 int get balance=>accounts.fold(0,(sum,a)=>sum+FinanceEngine.accountBalance(a,transactions));Map<String,int> get cashflow=>FinanceEngine.cashflowTotals(transactions);
}
